function validate([root]) {
  if (root.length > 0 && root[0] === null) return 'An empty tree is written as [].';
  const values = root.filter(v => v !== null);
  if (values.length > 10000) return 'The tree has at most 10^4 nodes.';
  if (values.some(v => !Number.isInteger(v) || v < -2147483648 || v > 2147483647)) return 'Each node value is a 32-bit signed integer.';
  return null;
}

