function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  const n = large ? 940 + pick(50) : pick(11);
  const mode = pick(3);
  // Values: the full 32-bit range, a few small ones (many ties), or mostly negative.
  const value = () => {
    if (large || mode === 0) return pick(4294967296) - 2147483648;
    if (mode === 1) return pick(4);
    const roll = rand();
    return roll < 0.1 ? -2147483648 : roll < 0.15 ? 2147483647 : -1 - pick(20);
  };
  const chainy = rand() < 0.3;
  if (n === 0) return [[]];
  const nodes = [{ val: value(), left: null, right: null }];
  for (let i = 1; i < n; i++) {
    const node = { val: value(), left: null, right: null };
    for (;;) {
      const parent = chainy ? nodes[nodes.length - 1 - pick(Math.min(2, nodes.length))] : nodes[pick(nodes.length)];
      const side = rand() < 0.5 ? 'left' : 'right';
      const other = side === 'left' ? 'right' : 'left';
      if (!parent[side]) { parent[side] = node; break; }
      if (!parent[other]) { parent[other] = node; break; }
    }
    nodes.push(node);
  }
  const out = [], queue = [nodes[0]];
  for (let q = 0; q < queue.length; q++) {
    const node = queue[q];
    if (!node) { out.push(null); continue; }
    out.push(node.val);
    queue.push(node.left, node.right);
  }
  while (out[out.length - 1] === null) out.pop();
  return [out];
}
